import math
import json

H = 1e-4
REL_TOL = 1e-4


def close(a, b):
    return abs(a - b) <= REL_TOL * (1.0 + abs(b))


def d(fn, s):
    return (fn(s + H) - fn(s - H)) / (2.0 * H)


# Candidate parametrizations x(t,s), y(t,s), u(t,s) from the options.
OPTIONS = {
    "1": lambda t, s: (3*t*(math.exp(s)-1), t/2*(math.exp(-s)+1), t*t*math.exp(-2*s)),
    "2": lambda t, s: (2*t*(math.exp(s)-1), t*(2*math.exp(2*s)-1), t*t/2*(1+math.exp(-2*s))),
    "3": lambda t, s: (2*t*(math.exp(s)-1), t/2*(math.exp(s)+1), t*t*math.exp(2*s)),
    "4": lambda t, s: (t*(math.exp(-s)-1), -2*t*(math.exp(-s)-1.5), t*t*(2*math.exp(-2*s)-1)),
}

# Charpit system for F = p*q - u = 0:
#   x' = F_p = q, y' = F_q = p, u' = p F_p + q F_q = 2pq,
#   p' = -(F_x + p F_u) = p, q' = -(F_y + q F_u) = q
# Initial strip x=0, y=tau, u=tau^2 gives q0 = du/dtau = 2tau, p0 = u0/q0 = tau/2.
TAUS = [-2.0, -0.5, 0.5, 1.0, 3.0]
S_VALS = [-0.4, 0.0, 0.3, 0.7]


def check_option(f):
    reasons = []
    for t in TAUS:
        x0, y0, u0 = f(t, 0.0)
        if not (close(x0, 0.0) and close(y0, t) and close(u0, t*t)):
            reasons.append("initial_curve")
            return False, reasons
        X = lambda z: f(t, z)[0]
        Y = lambda z: f(t, z)[1]
        U = lambda z: f(t, z)[2]
        for s in S_VALS:
            q = d(X, s)          # q = x_s
            p = d(Y, s)          # p = y_s
            us = d(U, s)
            ps = d(Y_s := (lambda z: d(Y, z)), s) if False else d(lambda z: d(Y, z), s)
            qs = d(lambda z: d(X, z), s)
            u = U(s)
            if not close(p*q, u):
                reasons.append("pq_ne_u")
                return False, reasons
            if not close(us, 2*p*q):
                reasons.append("u_ode")
                return False, reasons
            if not close(ps, p):
                reasons.append("p_ode")
                return False, reasons
            if not close(qs, q):
                reasons.append("q_ode")
                return False, reasons
        # Initial p0, q0 from the strip
        p0 = d(Y, 0.0)
        q0 = d(X, 0.0)
        if not (close(p0, t/2) and close(q0, 2*t)):
            reasons.append("initial_pq")
            return False, reasons
    return True, ["all_charpit_and_initial_checks_passed"]


results = {}
passing = []
for key, f in OPTIONS.items():
    ok, reasons = check_option(f)
    results[key] = {"passes": ok, "reason": reasons[0]}
    if ok:
        passing.append(key)

if len(passing) == 1:
    final = passing[0]
else:
    final = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "charpit_system": "x'=q, y'=p, u'=2pq, p'=p, q'=q",
        "initial_p0_q0": "p0=tau/2, q0=2tau",
        "closed_form_derived": "x=2tau(e^s-1), y=(tau/2)(e^s+1), u=tau^2 e^{2s}",
        "option_checks": results,
        "passing_options": passing
    }
}, sort_keys=True))
