import math

# Verification of the characteristic curves for p*q - u = 0 (p = u_x, q = u_y).
#
# Charpit system for F = p*q - u:
#   dx/ds = q, dy/ds = p, du/ds = 2pq, dp/ds = p, dq/ds = q
# Initial strip at s=0 (x=0, y=t, u=t^2): u_t = 2t = q, so q0 = 2t and p0 = u/q = t/2.
# Hence p = (t/2)e^s, q = 2t e^s, and
#   x = 2t(e^s - 1), y = (t/2)(e^s + 1), u = t^2 e^(2s),
# which is option 3.
#
# This script checks each option by sampling on a grid (floats, finite differences).
# Sampling can refute a claim but cannot prove a universal identity; the PASS
# verdicts below are SAMPLED checks, backed by the analytic derivation above.

H_INNER = 1e-6   # step for first partial derivatives
H_OUTER = 1e-3   # step for d/ds of recovered p, q
TOL = 1e-4
TS = [0.5, 1.0, 1.5, 2.0]
SS = [-0.5, 0.0, 0.3, 1.0]

def opt1(t, s):
    return (3*t*(math.exp(s) - 1), t/2*(math.exp(-s) + 1), t*t*math.exp(-2*s))

def opt2(t, s):
    return (2*t*(math.exp(s) - 1), t*(2*math.exp(2*s) - 1), t*t/2*(1 + math.exp(-2*s)))

def opt3(t, s):
    return (2*t*(math.exp(s) - 1), t/2*(math.exp(s) + 1), t*t*math.exp(2*s))

def opt4(t, s):
    return (t*(math.exp(-s) - 1), -2*t*(math.exp(-s) - 1.5), t*t*(2*math.exp(-2*s) - 1))

OPTIONS = {"1": opt1, "2": opt2, "3": opt3, "4": opt4}

def comp(opt, i):
    return lambda a, b: opt(a, b)[i]

def d(f, t, s, var):
    if var == 't':
        return (f(t + H_INNER, s) - f(t - H_INNER, s)) / (2*H_INNER)
    return (f(t, s + H_INNER) - f(t, s - H_INNER)) / (2*H_INNER)

def strip(opt, t, s):
    fx, fy, fu = comp(opt, 0), comp(opt, 1), comp(opt, 2)
    Xs, Xt = d(fx, t, s, 's'), d(fx, t, s, 't')
    Ys, Yt = d(fy, t, s, 's'), d(fy, t, s, 't')
    Us, Ut = d(fu, t, s, 's'), d(fu, t, s, 't')
    det = Xs*Yt - Ys*Xt
    # Strip conditions: U_s = p*X_s + q*Y_s, U_t = p*X_t + q*Y_t
    p = (Us*Yt - Ys*Ut) / det
    q = (Xs*Ut - Us*Xt) / det
    return p, q, det, Xs, Ys, Us

def verify(label, opt):
    # Initial curve: x=0, y=t, u=t^2 at s=0
    init_ok = all(
        abs(opt(t, 0.0)[0]) < 1e-12 and
        abs(opt(t, 0.0)[1] - t) < 1e-12 and
        abs(opt(t, 0.0)[2] - t*t) < 1e-12
        for t in TS)
    if not init_ok:
        print(f"option {label}: initial condition FAILS -> CHECK FAIL")
        return False

    worst = 0.0
    counter = None
    singular = False
    for t in TS:
        for s in SS:
            p, q, det, Xs, Ys, Us = strip(opt, t, s)
            if abs(det) < 1e-8:
                singular = True
                continue
            X, Y, U = opt(t, s)
            p_plus = strip(opt, t, s + H_OUTER)[0]
            p_minus = strip(opt, t, s - H_OUTER)[0]
            q_plus = strip(opt, t, s + H_OUTER)[1]
            q_minus = strip(opt, t, s - H_OUTER)[1]
            ps = (p_plus - p_minus) / (2*H_OUTER)
            qs = (q_plus - q_minus) / (2*H_OUTER)
            residuals = {
                "pde p*q-u": abs(p*q - U),
                "x_s-q": abs(Xs - q),
                "y_s-p": abs(Ys - p),
                "u_s-2pq": abs(Us - 2*p*q),
                "p_s-p": abs(ps - p),
                "q_s-q": abs(qs - q),
            }
            r = max(residuals.values())
            if r > worst:
                worst = r
            if r >= TOL and counter is None:
                bad = max(residuals, key=residuals.get)
                counter = (t, s, bad, residuals[bad])

    if singular:
        print(f"option {label}: singular Jacobian at some sample -> CHECK UNKNOWN")
        return None
    if counter is None:
        print(f"option {label}: max residual {worst:.3e} over {len(TS)*len(SS)} samples "
              f"(SAMPLED, not a universal proof) -> CHECK PASS")
        return True
    t, s, bad, val = counter
    print(f"option {label}: counterexample t={t}, s={s}, failing {bad}, residual {val:.3e} "
          f"(max over grid {worst:.3e}) -> CHECK FAIL")
    return False

results = {}
for lab, opt in OPTIONS.items():
    results[lab] = verify(lab, opt)

passing = [lab for lab, r in results.items() if r is True]
print("passing options (sampled):", passing)

submitted = "1"
if results[submitted] is False:
    print("submitted answer: option 1 -> CHECK FAIL")
elif results[submitted] is True:
    print("submitted answer: option 1 -> CHECK PASS (sampled)")
else:
    print("submitted answer: option 1 -> CHECK UNKNOWN")

if passing == ["3"]:
    print("expected characteristic set: option 3 (unique passing option)")
    print("analytic: p=(t/2)e^s, q=2t e^s, du/ds=2pq=2u -> u=t^2 e^(2s)")
else:
    print("UNSUPPORTED: sampling did not isolate a unique option")
