import json

N = 33146799

def is_prime(m):
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True

def prime_factors(m):
    factors = []
    d = 2
    while d * d <= m:
        while m % d == 0:
            factors.append(d)
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors.append(m)
    return factors

factors = prime_factors(N)

product = 1
for p in factors:
    product *= p

all_prime = all(is_prime(p) for p in factors)
sorted_ok = factors == sorted(factors)

checks = {
    "product_equals_n": product == N,
    "all_factors_prime": all_prime,
    "nondecreasing_order": sorted_ok,
}

if all(checks.values()) and factors:
    final_answer = ", ".join(str(p) for p in factors)
