import json
from itertools import combinations

# Each item type is a pair (p, q) of booleans.
# A model is any nonempty set of item types; existential claims depend only on which types occur,
# so checking all 15 nonempty subsets of the 4 types is an exhaustive finite check.
TYPES = [(True, True), (True, False), (False, True), (False, False)]

def models():
    for r in range(1, len(TYPES) + 1):
        for combo in combinations(TYPES, r):
            yield combo

def some_x_not_y(model, x, y):
    # "Some X are not Y" and "Not all X are Y" both mean: exists an item with X true and Y false.
    return any(getattr_pair(t, x) and not getattr_pair(t, y) for t in model)

def getattr_pair(t, idx):
    return t[0] if idx == 0 else t[1]

# Each option: (premise_pair, conclusion_pair) where each is (x_index, y_index) meaning
# the statement "some X are not Y" (existential form). Conclusions of the form
# "not all X are Y" are the same existential statement with the roles given.
# Given argument: premise "some G not C" (G=0,C=1); conclusion "not all C are G" -> some C not G.
options = {
    "Given": {"premise": (0, 1), "conclusion": (1, 0)},
    # A: "Some Hunan people do not like pepper" -> some H not P; "some pepper lovers not from Hunan" -> some P not H
    "A": {"premise": (0, 1), "conclusion": (1, 0)},
    # B: "Some people are not selfish" -> some P not S; "not all people are selfish" -> some P not S
    "B": {"premise": (0, 1), "conclusion": (0, 1)},
    # C: "good motive not necessarily good effect" -> some M not E; "good results not necessarily from good motive" -> some E not M
    "C": {"premise": (0, 1), "conclusion": (1, 0)},
    # D: "some southerners not Cantonese" -> some S not C; "not all Cantonese are southerners" -> some C not S
    "D": {"premise": (0, 1), "conclusion": (1, 0)},
}

def check_validity(spec):
    counterexample = None
    for m in models():
        p = some_x_not_y(m, *spec["premise"])
        c = some_x_not_y(m, *spec["conclusion"])
        if p and not c:
            counterexample = [list(t) for t in m]
            break
    return counterexample is None, counterexample

results = {}
for name, spec in options.items():
