    "B": ("FR", "GB", "DE", "KR"),
    "C": ("DE", "GB", "FR", "KR"),
    "D": ("DE", "GB", "KR", "FR"),
}
NAME = {"KR": "South Korea", "FR": "France", "GB": "Britain", "DE": "Germany"}


def solve():
    solutions = []
    for order in permutations(PEOPLE):  # order[i] lives in room i+1
        room = {p: i + 1 for i, p in enumerate(order)}

        def neighbors(p):
            return [q for q in PEOPLE if q != p and abs(room[q] - room[p]) == 1]

        def talks(p, q):
            # Two people can communicate when they share at least one language.
            return bool(LANG[p] & LANG[q])

        # Korean: my room number is larger than the German's; speaks no foreign
        # language; communicates with no neighbor.
        kr_ok = (
            room["KR"] > room["DE"]
            and LANG["KR"] == {"KR"}
            and not any(talks("KR", q) for q in neighbors("KR"))
        )
        # French: speaks German; communicates with no neighbor.
        fr_ok = (
            "DE" in LANG["FR"]
            and not any(talks("FR", q) for q in neighbors("FR"))
        )
